"},{"carte":"3708d7fe-9311-52f4-8301-214a53912d6f","tag":"mode"},{"carte":"3708d7fe-9311-52f4-8301-214a53912d6f","tag":"trois-d"},{"carte":"a11952e4-9f8d-5c74-b52f-4f23c6f75e87","tag":"fantasy"},{"carte":"a11952e4-9f8d-5c74-b52f-4f23c6f75e87","tag":"animaux"},{"carte":"a11952e4-9f8d-5c74-b52f-4f23c6f75e87","tag":"trois-d"},{"carte":"a11952e4-9f8d-5c74-b52f-4f23c6f75e87","tag":"humour"},{"carte":"6bdc5dc6-f975-52eb-a266-c5677521e848","tag":"fantasy"},{"carte":"6bdc5dc6-f975-52eb-a266-c5677521e848","tag":"animaux"},{"carte":"6bdc5dc6-f975-52eb-a266-c5677521e848","tag":"coupe"},{"carte":"6bdc5dc6-f975-52eb-a266-c5677521e848","tag":"trois-d"}]$raccourcia$) as j(carte text, tag text) on j.carte = l.carte_id
join public.tags t on t.slug = j.tag
on conflict (prompt_id, tag_id) do nothing;

do $ctrl$
declare
  v_posees integer;
  v_attendues integer;
  v_sans_rayon integer;
begin
  select count(*) into v_attendues from lot_v3;
  select count(*) into v_posees
  from lot_v3 l join public.prompts p on p.card_id = l.carte_id;
  select count(*) into v_sans_rayon
  from lot_v3 l join public.prompts p on p.card_id = l.carte_id
  where p.category_id is null;

  if v_posees <> v_attendues then
    raise exception 'Lot 105 : % cartes sur % posees.', v_posees, v_attendues;
  end if;
  if v_sans_rayon > 0 then
    raise exception 'Lot 105 : % cartes sans rayon.', v_sans_rayon;
  end if;
end $ctrl$;

drop table lot_v3;

